mapper.update:
UPDATE base_job SET last_job_log_id = #{record.id}, last_execute_time = #{record.beginTime},
    last_end_time = NULL, last_status = 1, last_duration_ms = NULL,
    last_dispatch_duration_ms = NULL, last_tracking_version = #{record.trackingVersion}
WHERE 
  AND (last_execute_time IS NULL OR last_execute_time < #{record.beginTime}
    OR (last_execute_time = #{record.beginTime}
      AND (last_job_log_id IS NULL OR last_job_log_id < #{record.id})))

UPDATE base_job SET last_end_time = #{record.endTime}, last_status = #{record.status.value},
    last_duration_ms = #{record.durationMs}, last_dispatch_duration_ms = #{record.dispatchDurationMs},
    last_tracking_version = #{record.trackingVersion}
WHERE  AND last_job_log_id = #{record.id}
